/**
 * OCR + extraction accuracy on SYNTHETIC receipt images (evals/receipts, generated by generate.py).
 * Engine: tesseract.js (free, local). Extractors: rules only, and rules+LLM when LLM_BASE_URL is set (FreeLLMAPI).
 * Usage: npx tsx scripts/eval-ocr.ts  -> evals/results/ocr-latest.json. Not a CI gate (needs ~10 MB language data).
 */
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { LlmAssistedExtractor, TextReceiptExtractor, type DocumentExtractor } from "../packages/books/src/index.js";
import { openAiCompatible } from "../packages/pipeline/src/index.js";
import { TesseractOcr } from "../apps/api/dev/tesseract-ocr.js";

const ROOT = fileURLToPath(new URL("..", import.meta.url));
type Truth = { file: string; vendor: string; date: string; totalPence: number; vatPence: number | null };
const truth: Truth[] = JSON.parse(readFileSync(`${ROOT}evals/receipts/truth.json`, "utf8"));
const ocr = new TesseractOcr(`${ROOT}.local/tesseract-cache`);
const rules = new TextReceiptExtractor();
const llm = process.env.LLM_BASE_URL
  ? openAiCompatible(process.env.LLM_BASE_URL, process.env.LLM_API_KEY ?? "", process.env.LLM_MODEL ?? "auto", fetch, 30_000)
  : null;
const extractors: DocumentExtractor[] = [rules, ...(llm ? [new LlmAssistedExtractor(rules, llm)] : [])];

const score = Object.fromEntries(
  extractors.map((e) => [e.name, { total: 0, vat: 0, date: 0, vendor: 0, allFields: 0, flaggedWhenWrong: 0, wrong: 0, autoOkButWrong: 0 }]),
);
let ocrConf = 0;
const t0 = Date.now();
for (const t of truth) {
  const o = await ocr.recognise({ bytes: readFileSync(`${ROOT}evals/receipts/${t.file}`), contentType: "image/png" });
  ocrConf += o.confidence;
  for (const e of extractors) {
    const r = await e.extract({ text: o.text });
    const s = score[e.name]!;
    const ok = {
      total: r.totalPence === t.totalPence,
      vat: (r.vatPence ?? null) === t.vatPence || (t.vatPence === null && r.vatPence === 0),
      date: r.date === t.date,
      vendor: !!r.vendor && r.vendor.toLowerCase().includes(t.vendor.toLowerCase().split(" ")[0]!),
    };
    for (const k of ["total", "vat", "date", "vendor"] as const) if (ok[k]) s[k]++;
    const all = ok.total && ok.vat && ok.date;
    if (all) s.allFields++;
    else {
      s.wrong++;
      if (r.needsReview) s.flaggedWhenWrong++;
      else s.autoOkButWrong++;
    }
  }
}
await ocr.close();
const n = truth.length;
const pct = (x: number) => Math.round((x / n) * 1000) / 10;
const out = {
  ranAt: new Date().toISOString(),
  data: "synthetic receipts (evals/receipts, seeded generator); NOT real-world receipts",
  engine: ocr.name,
  receipts: n,
  meanOcrConfidence: Math.round((ocrConf / n) * 100) / 100,
  seconds: Math.round((Date.now() - t0) / 100) / 10,
  llm: llm ? (process.env.LLM_MODEL ?? "auto") : null,
  results: Object.fromEntries(
    Object.entries(score).map(([k, s]) => [
      k,
      {
        totalPct: pct(s.total),
        vatPct: pct(s.vat),
        datePct: pct(s.date),
        vendorPct: pct(s.vendor),
        allThreePct: pct(s.allFields),
        wrong: s.wrong,
        wrongButFlaggedForReview: s.flaggedWhenWrong,
        wrongAndNotFlagged: s.autoOkButWrong,
      },
    ]),
  ),
};
mkdirSync(`${ROOT}evals/results`, { recursive: true });
writeFileSync(`${ROOT}evals/results/ocr-latest.json`, JSON.stringify(out, null, 1));
console.log(JSON.stringify(out, null, 1));
